DO $source_identity_cover$BEGIN IF pg_get_indexdef('public.accounting_tournament_source_identity_keys_cover'::regclass)IS DISTINCT FROM $source_cover_definition$CREATE INDEX accounting_tournament_source_identity_keys_cover ON public.accounting_tournament_fee_sources USING btree (id) INCLUDE (tournament_id, rake_record_id)$source_cover_definition$ OR NOT EXISTS(SELECT FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am am ON am.oid=c.relam WHERE i.indexrelid='public.accounting_tournament_source_identity_keys_cover'::regclass AND i.indrelid='public.accounting_tournament_fee_sources'::regclass AND c.relowner='postgres'::regrole AND c.relkind='i'AND am.amname='btree'AND i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisunique AND i.indnkeyatts=1 AND i.indnatts=3 AND i.indexprs IS NULL AND i.indpred IS NULL)THEN RAISE EXCEPTION 'selected_source_exact_existing_identity_cover_required';END IF;END$source_identity_cover$;
